local ResidentBondPanel = Class("ResidentBondPanel")
local AttrCellPath = "Game.UI.ResidentEvent.ResidentBondPanelAttrCell"
local KTool = CS.Engine.Lib.KTool
local UIGrayGraphics    = typeof(CS.Engine.UI.UIGrayGraphics)
local RewardDayCount = 4
local UIModule          = CS.Engine.UI.UIModule

function ResidentBondPanel:__init()
    self.data = nil
    self.serverData = nil
    self.attrEnv = {}
    self.totalDay = nil
    self.rewardEnv = {}
end

function ResidentBondPanel:__delete()
    self.data = nil
    self.serverData = nil
    self.attrEnv = nil
    self.totalDay = nil
    self.controller = nil
    self.rewardEnv = nil
end

function ResidentBondPanel:Awake()
    self.totalDay = self:GetParamsDataById(3)
    self:InitRewardEnv()
    self:AddUIClick()
end

function ResidentBondPanel:AddUIClick()
    SetButtonAction(self.BtnBond,Bind(self,self.OnBtnBondClick))
    SetButtonAction(self.BtnReward,Bind(self,self.OnBtnRewardClick))
    local BtnRewardTrans = self.AdditionRoot.transform.parent.parent:Find("TitleItem/Tips/BtnReward")
    if BtnRewardTrans then
        SetButtonAction(BtnRewardTrans, function()
            ---显示说明面板
            local moduleId = self:GetParamsDataById(6)
            CfUtils.ShowModuleToast(moduleId)
        end)
    end
end

function ResidentBondPanel:InitRewardEnv()
    for i = 1, RewardDayCount do
        local dayItem = self["TxtDay"..i]
        if dayItem then
            local env = CfUtils.GetLuaScr(dayItem,"Game.UI.ResidentEvent.ResidentBondPanelDayCell")
            if isNotNull(env) then
                env:InitCallBack(Bind(self,self.OnRewardCellClick))
               self.rewardEnv[i] = env
            end
        end
    end

    local env = CfUtils.GetLuaScr(self.Cell.gameObject,AttrCellPath)
    if isNotNull(env) then
        table.insert(self.attrEnv,env)
    end
end

function ResidentBondPanel:GetParamsDataById(refId)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6444,"DailyInvestParamsVo",refId)
    return checkNumber(vo.num)
end

function ResidentBondPanel:Refresh(data)
    if not data then return end
    self.data = data
    self:RefreshRedPoint()
    GameUtils.Request(Interfaces.WelfareDailyInvestHome,{},function(request,response)
        if  checkInt(response.errCode) == 0  then
            local data = response.data
            self.serverData = data
            self:RefreshShow()
        end
    end )
end

function ResidentBondPanel:RefreshRedPoint()
    local playerDojo = GameUtils.GetPlayerDojo()
    local dailyTime = playerDojo:GetDailyRefreshTime()
    local refreshTime = GameUtils.GetServerTime() + checkNumber(dailyTime)
    CfUtils.WriteLocalData("ResidentBondPanelDailyInvest", checkNumber(refreshTime))
    GameUtils.SetRedPointNum(Constants.RedPointConst.DailyInvest, 0)
end

function ResidentBondPanel:RefreshShow()
    self:RefreshAttrShow()
    self:RefreshSliderShow()
    self:RefreshBtnShow()
    self:RefreshRewardShow()
    self:RefreshBigRewardShow()
end

function ResidentBondPanel:RefreshAttrShow()
    for i, v in ipairs(self.serverData.addition) do
        if isNull(self.attrEnv[i]) then
            local go = CS.UnityEngine.GameObject.Instantiate(self.Cell.gameObject)
            KTool.SetParent(go,self.AdditionRoot.gameObject,false)
            local env = CfUtils.GetLuaScr(go,AttrCellPath)
            if env then
                env:RefreshShow(v)
                self.attrEnv[i] = env
            end
        else
            self.attrEnv[i]:RefreshShow(v)
        end
    end
end

function ResidentBondPanel:RefreshSliderShow()
    self.ImgFill.fillAmount = checkNumber(self.serverData.investCheckinTimes)/self.totalDay
    CfUtils.FillText(self.TxtTips,localize("当前累计投资_num_天",{_num_ = self.serverData.investCheckinTimes}))
end

function ResidentBondPanel:RefreshBtnShow()
    local isInvest = checkNumber(self.serverData.isCheckin)  == 1
    self.BtnBond.transform:GetComponent(UIGrayGraphics):MarkGray(isInvest)
    CfUtils.FillText(self.TxtTitle,isInvest and localize("今日已投资") or localize("点击投资"))

    local goodsId = self:GetParamsDataById(1)
    local num = self:GetParamsDataById(2)
    UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, goodsId, num)
end

function ResidentBondPanel:RefreshRewardShow()
    for i, v in ipairs(self.rewardEnv) do
        v:RefreshShow(i,self.serverData)
    end
end

function ResidentBondPanel:RefreshBigRewardShow()
    local isCanGet = self.serverData.investCheckinTimes == self.totalDay
    CfUtils.SetActive(self.NotGet.gameObject,not isCanGet)
    CfUtils.SetActive(self.Get.gameObject, isCanGet)
    if not isCanGet then
        local env = CfUtils.GetLuaScr(self.CommonCurrencyNode,"Game.Behaviours.CommonCurrencyNode")
        if env then
            local goodsId = self:GetParamsDataById(4)
            local goodsNum = self:GetParamsDataById(2) * self.serverData.investCheckinTimes
           env:SetCurrencyShow(goodsId, goodsNum)
        end
    end
end

function ResidentBondPanel:IsGetAllNormalReward()
    local isGetAll = true
    for i = 1, RewardDayCount do
        local isGet = self:IsGetReward(i)
        if not isGet then
            isGetAll = false
            break
        end
    end
    return isGetAll
end

function ResidentBondPanel:IsGetReward(id)
    for i, v in ipairs(self.serverData.drawInvestRewardIds) do
        if tonumber(v) == tonumber(id) then
            return true
        end
    end
    return false
end

function ResidentBondPanel:OnRewardCellClick(index)
    GameUtils.Request(Interfaces.WelfareDailyDrawReward,{id = index},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local responseData = response.data
            self:UpdateReceiveData(index)
            if table.count(responseData.rewards) > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                self.rewardEnv[index]:RefreshShow(index,self.serverData)
            end
        end
    end)
end

function ResidentBondPanel:OnBtnRewardClick()
    local isCanGet = self.serverData.investCheckinTimes == self.totalDay
    if not isCanGet then
        GameUtils.Toast(localize("累计投资天数不足"))
        return
    end

    local isGetAllReward = self:IsGetAllNormalReward()
    if not isGetAllReward then
        GameUtils.Toast(localize("请先领取进度奖励"))
        return
    end

    GameUtils.Request(Interfaces.WelfareDailyDrawBigReward,{},function(request,response)
        if checkNumber(response.errCode)  == 0 then
            local responseData = response.data
            if table.count(responseData.rewards) > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards }})
                self:UpdateServerData()
                self:UpdateShow()
            end
        end
    end)
end

function ResidentBondPanel:UpdateShow()
    self:RefreshRewardShow()
    self:RefreshSliderShow()
    self:RefreshBigRewardShow()
end

function ResidentBondPanel:UpdateServerData()
    self.serverData.investCheckinTimes = 0
    self.serverData.drawInvestRewardIds = {}
end

function ResidentBondPanel:OnBtnBondClick()
    local isInvest = checkNumber(self.serverData.isCheckin)  == 1
    if isInvest then
        GameUtils.Toast(localize("今日已投资"))
        return
    end

    local isToMax = self.serverData.investCheckinTimes == self.totalDay
    if isToMax then
        GameUtils.Toast(localize("投资已达上限，请先领取所有奖励"))
        return
    end

    local goodsId = self:GetParamsDataById(1)
    local goodsNum = self:GetParamsDataById(2)
    GameUtils.SecondConfirm(localize("是否消耗以下资源进行投资？"),function()
        local haveNum = GoodsUtils.GetThingNo(goodsId)
        if haveNum >= goodsNum then
            GameUtils.Request(Interfaces.WelfareDailyInvest, {},function(request,response)
                if checkNumber(response.errCode) == 0 then
                    GoodsUtils.DrawRewards({ { goodsId = goodsId, num = - goodsNum } }, true)
                    self.serverData.isCheckin = 1
                    self.serverData.investCheckinTimes = self.serverData.investCheckinTimes + 1
                    local index = response.data.additionId
                    if index > 0 then
                        self.serverData.addition[index].playerAddition = response.data.num
                        self:RefreshSingleAttr(index)
                        self:RefreshGlobalAttrAdd(self.serverData.addition[index].attrId,response.data.num)
                    end

                    self:UpdateShow()
                    self:RefreshBtnShow()

                    GameUtils.StartFlyGoods1(self.BtnBond.gameObject, self.BtnReward.gameObject, goodsId,true)
                end
            end)
        else
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            GameUtils.Toast(localize("_name_不足",{_name_ = goodsVo.name}))
        end
    end,nil,nil,6,{{goodsId = goodsId ,num = goodsNum }})
end

function ResidentBondPanel:RefreshGlobalAttrAdd(attrId,value)
    local DailyInvestMgr = import('Game.UI.ResidentEvent.DailyInvestMgr')
    DailyInvestMgr:GetInstance():UpdatePropertyData(attrId,value)
end

function ResidentBondPanel:RefreshSingleAttr(index)
    self.attrEnv[index]:RefreshSingleShow(self.serverData.addition[index])
end

function ResidentBondPanel:UpdateReceiveData(index)
    table.insert(self.serverData.drawInvestRewardIds,index)
end

function ResidentBondPanel:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ResidentBondPanel